document.querySelectorAll("[data-goatcounter-event]").forEach(function(t){t.addEventListener("click",function(){window.goatcounter&&"function"==typeof window.goatcounter.count&&window.goatcounter.count({path:t.dataset.goatcounterEvent,title:t.dataset.goatcounterTitle||t.dataset.goatcounterEvent,event:!0})})});